css:
.d-blur-in-kf{font-size:15px;padding:14px 18px;border-radius:10px;background:var(--paper);border:1px solid var(--line);animation:d-blur-in-kf .5s var(--ease) forwards}
@keyframes d-blur-in-kf{from{filter:blur(10px);opacity:0}to{filter:blur(0);opacity:1}}
.d-btn{font:inherit;font-size:13px;padding:8px 16px;border-radius:10px;border:1px solid var(--line);background:var(--paper);color:var(--ink);cursor:pointer;transition:transform 180ms var(--ease),background-color 180ms,color 180ms,border-color 180ms}
.d-btn:hover{box-shadow:0 6px 18px #20241e14}
.d-btn:active{transform:scale(.97)}

init:
root => root.querySelector('[data-replay]')?.addEventListener('click', () => {
    const el = root.querySelector('.d-blur-in-kf'); el.style.animation = 'none'; void el.offsetWidth; el.style.animation = '';
  })
